<script setup lang="ts">
import { computed, onActivated, onDeactivated, onMounted, onUnmounted, ref } from "vue";
import { RouterLink, useRoute } from "vue-router";
import FolioIcon from "../components/FolioIcon.vue";
import { formatLocal, responseError, unwrapPayload, type GuadaoLog } from "./guadao_shared";

type RawLog = Record<string, unknown>;
type LogMeta = { retentionDays?: number; diskUsageMb?: number; fileCount?: number; streamStatus?: string; startAt?: string; endAt?: string };
type LogsPayload = { logs?: GuadaoLog[]; events?: RawLog[]; items?: RawLog[]; total?: number; page?: number; pageSize?: number; hasMore?: boolean; storage?: Record<string,unknown>; meta?: LogMeta };
const route=useRoute();
const logs=ref<GuadaoLog[]>([]);const meta=ref<LogMeta>({});const selectedId=ref<string|number|null>(null);const loading=ref(false);const error=ref("");const paused=ref(false);const buffered=ref<GuadaoLog[]>([]);const streamConnected=ref(false);const hasMore=ref(false);const total=ref(0);
const startAt=ref("");const endAt=ref("");const level=ref("");const service=ref("");const operation=ref("");const httpStatus=ref(String(route.query.httpStatus||""));const operationId=ref(String(route.query.operationId||""));const account=ref(String(route.query.account||""));const marketHashName=ref(String(route.query.marketHashName||""));const keyword=ref(String(route.query.q||""));const includeScheduler=ref(false);const page=ref(1);const pageSize=ref(20);
let source:EventSource|null=null;
const seenEventIds=new Set<string>();

const selected=computed(()=>logs.value.find(row=>(row.id??`${row.timestamp}-${row.requestId}`)===selectedId.value)||logs.value[0]||null);
const services=computed(()=>[...new Set(logs.value.map(row=>row.service).filter(Boolean))] as string[]);const operations=computed(()=>[...new Set(logs.value.map(row=>row.operation).filter(Boolean))] as string[]);
const selectedDetail=computed<Record<string,unknown>>(()=>selected.value?.detail&&typeof selected.value.detail==="object"?selected.value.detail:{});
const requestFrequency=computed<Record<string,unknown>>(()=>{const value=selectedDetail.value.request_frequency||selectedDetail.value.requestFrequency;return value&&typeof value==="object"?value as Record<string,unknown>:{};});
const relatedOperationQuery=computed(()=>String(selected.value?.operationId||selected.value?.tradeNo||selected.value?.marketHashName||"").replace(/^GD-/i,""));
const redactedError=computed(()=>{const detail=selectedDetail.value;const result=detail.result&&typeof detail.result==="object"?detail.result as Record<string,unknown>:{};const value=detail.error||detail.lastError||result.lastError;return String(value||((selected.value?.httpStatus||0)>=400?selected.value?.message||"HTTP 请求失败":""));});
function rowId(row:GuadaoLog):string|number{return row.id??`${row.timestamp}-${row.requestId}-${row.operation}`}
function eventId(row:GuadaoLog):string{return String(row.id||"").trim()}
function rememberRows(rows:GuadaoLog[]):void{for(const row of rows){const id=eventId(row);if(id)seenEventIds.add(id)}}
function normalizeLog(raw:RawLog):GuadaoLog{const candidate=raw.safe_context&&typeof raw.safe_context==="object"?raw.safe_context:raw.detail&&typeof raw.detail==="object"?raw.detail:{};const context=candidate as Record<string,unknown>;return{id:String(raw.event_id||raw.id||""),timestamp:String(raw.timestamp_utc||raw.timestamp||""),level:String(raw.level||""),service:String(raw.component||raw.provider||raw.service||""),operation:String(raw.operation||""),marketHashName:String(raw.market_hash_name||raw.marketHashName||context.marketHashName||"")||null,accountName:String(raw.account_id||raw.steam_id64||raw.accountName||"")||null,httpStatus:raw.status_code==null?(raw.httpStatus as number|null):Number(raw.status_code),durationMs:raw.elapsed_ms==null?(raw.durationMs as number|null):Number(raw.elapsed_ms),message:String(raw.message||""),requestId:String(raw.request_id||raw.requestId||"")||null,operationId:(raw.operationId||raw.trade_id||context.operationId||context.businessOperationId) as string|number|null,tradeNo:String(raw.tradeNo||raw.trade_no||"")||null,caller:String(raw.caller||context.source||raw.source||"guadao"),endpoint:String(raw.endpoint||"")||null,retryAfter:(raw.retry_after??raw.retryAfter) as string|number|null,detail:context}}
function buildParams():URLSearchParams{const params=new URLSearchParams({page:String(page.value),pageSize:String(pageSize.value),includeSteamScheduler:String(includeScheduler.value)});if(startAt.value)params.set("startAt",new Date(startAt.value).toISOString());if(endAt.value)params.set("endAt",new Date(endAt.value).toISOString());if(level.value)params.set("level",level.value);if(service.value)params.set("service",service.value);if(operation.value)params.set("operation",operation.value);if(httpStatus.value)params.set("httpStatus",httpStatus.value);if(operationId.value.trim())params.set("operationId",operationId.value.trim());if(account.value.trim())params.set("account",account.value.trim());if(marketHashName.value.trim())params.set("marketHashName",marketHashName.value.trim());if(keyword.value.trim())params.set("q",keyword.value.trim());return params}
async function refresh():Promise<void>{loading.value=true;try{const response=await fetch(`/api/guadao/logs?${buildParams()}`,{cache:"no-store"});if(!response.ok)throw new Error(await responseError(response));const data=unwrapPayload<LogsPayload>(await response.json());const rawRows=data.events||data.items||[];logs.value=data.logs||rawRows.map(normalizeLog);rememberRows(logs.value);total.value=Number(data.total??logs.value.length);hasMore.value=Boolean(data.hasMore);const storage=data.storage||{};meta.value=data.meta||{retentionDays:Number(storage.retentionDays||0)||undefined,diskUsageMb:storage.totalBytes==null?undefined:Number(storage.totalBytes)/1024/1024,fileCount:Number(storage.fileCount||0),startAt:String(storage.earliestTimestamp||"")||undefined,endAt:String(storage.latestTimestamp||"")||undefined};if(selectedId.value==null||!logs.value.some(row=>rowId(row)===selectedId.value))selectedId.value=logs.value[0]?rowId(logs.value[0]):null;error.value="";}catch(reason){error.value=reason instanceof Error?reason.message:String(reason)}finally{loading.value=false}}
function handleStreamEvent(event:Event):void{try{const row=normalizeLog(JSON.parse((event as MessageEvent<string>).data) as RawLog);const id=eventId(row);if(id&&seenEventIds.has(id))return;if(id)seenEventIds.add(id);if(paused.value){buffered.value.push(row);if(buffered.value.length>500)buffered.value.shift();return}if(page.value===1)logs.value=[row,...logs.value].slice(0,pageSize.value)}catch{}}
function connect():void{disconnect();const params=buildParams();params.delete("page");params.delete("pageSize");const latestId=page.value===1&&logs.value.length?eventId(logs.value[0]):"";if(latestId)params.set("lastEventId",latestId);source=new EventSource(`/api/guadao/logs/stream?${params}`);source.onopen=()=>{streamConnected.value=true};source.onerror=()=>{streamConnected.value=false};source.addEventListener("guadao_log",handleStreamEvent)}
function disconnect():void{source?.close();source=null;streamConnected.value=false}
function togglePause():void{paused.value=!paused.value;if(!paused.value&&buffered.value.length){logs.value=[...buffered.value.reverse(),...logs.value].slice(0,pageSize.value);buffered.value=[]}}
async function query():Promise<void>{page.value=1;disconnect();await refresh();connect()}
function previousPage():void{if(page.value<=1)return;page.value-=1;void refresh()}
function followingPage():void{if(!hasMore.value)return;page.value+=1;void refresh()}
function exportLogs(format:"jsonl"|"csv"):void{const params=buildParams();params.set("format",format);params.delete("page");params.delete("pageSize");window.location.href=`/api/guadao/logs/export?${params}`}
onMounted(()=>{void (async()=>{await refresh();connect()})()});onActivated(connect);onDeactivated(disconnect);onUnmounted(disconnect);
</script>

<template>
  <main class="page logs-page">
    <header class="logs-heading"><div><p class="eyebrow">Guadao Operations</p><h1>挂刀实时日志</h1><p>只记录 source=guadao 的挂刀活动；共享 Steam 请求对照仅展示脱敏元数据</p></div><div class="stream-actions"><span :class="['stream-state',{online:streamConnected}]"><i></i>{{streamConnected?"实时连接正常":"实时连接断开"}}</span><button class="secondary-button" type="button" @click="togglePause"><FolioIcon :name="paused?'play':'pause'" :size="14" />{{paused?`继续显示（${buffered.length}）`:"暂停显示"}}</button><button class="secondary-button" type="button" @click="connect"><FolioIcon name="refresh" :size="14" />重新连接</button></div></header>
    <p v-if="error" class="api-error">日志 API 请求失败：{{error}}</p>
    <section class="log-metrics"><article><span>日志来源</span><strong>Guadao</strong></article><article><span>保留策略</span><strong>{{meta?.retentionDays?`${meta.retentionDays} 天 · 闭日压缩`:"—"}}</strong></article><article><span>磁盘占用</span><strong>{{meta?.diskUsageMb==null?"—":`${meta.diskUsageMb.toFixed(1)} MB`}}</strong></article><article><span>日志文件</span><strong>{{meta?.fileCount??"—"}}</strong></article><article><span>时间范围</span><strong>{{meta?.startAt?`${formatLocal(meta.startAt)} — ${formatLocal(meta.endAt)}`:"—"}}</strong></article></section>
    <section class="panel log-filters">
      <div class="filter-row"><label><span>开始时间（北京时间）</span><input v-model="startAt" type="datetime-local" /></label><label><span>结束时间</span><input v-model="endAt" type="datetime-local" /></label><label><span>级别</span><select v-model="level"><option value="">全部</option><option>DEBUG</option><option>INFO</option><option>WARN</option><option>ERROR</option></select></label><label><span>HTTP 状态</span><select v-model="httpStatus"><option value="">全部</option><option value="2xx">2xx</option><option value="4xx">4xx</option><option value="5xx">5xx</option><option value="429">429</option><option value="error">全部错误</option></select></label><label><span>操作</span><select v-model="operation"><option value="">全部</option><option v-for="value in operations" :key="value">{{value}}</option></select></label></div>
      <div class="filter-row second"><label><span>流水 ID</span><input v-model="operationId" placeholder="GD-123 / 123" /></label><label><span>Steam 账号</span><input v-model="account" placeholder="输入账号" /></label><label><span>marketHashName</span><input v-model="marketHashName" placeholder="输入物品名" /></label><label><span>服务</span><select v-model="service"><option value="">全部</option><option v-for="value in services" :key="value">{{value}}</option></select></label><label><span>关键词</span><input v-model="keyword" placeholder="请求 ID / 错误摘要" @keyup.enter="query" /></label></div>
      <div class="filter-row third"><label class="scheduler-check" title="只增加跨执行器 Steam 请求调度元数据，不混入 Profit/Notify 业务日志"><input v-model="includeScheduler" type="checkbox" @change="query" /><span>包含跨执行器 Steam 调度元数据</span></label><div class="filter-actions"><button class="primary-button" :disabled="loading" @click="query">{{loading?"查询中…":"查询日志"}}</button><button class="secondary-button" @click="exportLogs('jsonl')">导出 JSONL</button><button class="secondary-button" @click="exportLogs('csv')">导出 CSV</button></div></div>
    </section>
    <section class="log-workbench"><div class="panel log-table-panel"><div class="table-wrap"><table class="data-table log-table"><thead><tr><th>北京时间</th><th>级别</th><th>服务</th><th>操作</th><th>流水 / 物品</th><th>Steam 账号</th><th>HTTP</th><th>耗时</th><th>摘要</th></tr></thead><tbody><tr v-for="row in logs" :key="rowId(row)" :class="[{selected:selected&&rowId(selected)===rowId(row)},row.level?.toLowerCase()]" @click="selectedId=rowId(row)"><td>{{formatLocal(row.timestamp)}}</td><td><span :class="['level-pill',row.level?.toLowerCase()]">{{row.level||"—"}}</span></td><td>{{row.service||"—"}}</td><td>{{row.operation||"—"}}</td><td>{{row.marketHashName||"—"}}</td><td>{{row.accountName||"—"}}</td><td :class="{'http-error':(row.httpStatus||0)>=400}">{{row.httpStatus||"—"}}</td><td>{{row.durationMs==null?"—":`${row.durationMs} ms`}}</td><td>{{row.message||"—"}}</td></tr></tbody></table></div><div v-if="!logs.length" class="empty-state">{{loading?"正在读取日志…":"当前筛选没有日志记录。"}}</div><footer v-if="logs.length||page>1" class="pagination"><span>第 {{page}} 页 · 本页 {{logs.length}} 条</span><select v-model.number="pageSize" @change="query"><option :value="20">20 条/页</option><option :value="50">50 条/页</option><option :value="100">100 条/页</option></select><button :disabled="page<=1" @click="previousPage">上一页</button><button :disabled="!hasMore" @click="followingPage">下一页</button></footer></div>
      <aside class="panel log-detail"><template v-if="selected"><header><strong>请求详情</strong><span>{{selected.level||"—"}}</span></header><dl><div><dt>caller</dt><dd>{{selected.caller||"guadao"}}</dd></div><div><dt>关联流水</dt><dd>{{selected.tradeNo||selected.operationId||"—"}}</dd></div><div><dt>Steam账号</dt><dd>{{selected.accountName||"—"}}</dd></div><div><dt>endpoint</dt><dd>{{selected.endpoint||"—"}}</dd></div><div><dt>HTTP 状态</dt><dd :class="{'http-error':(selected.httpStatus||0)>=400}">{{selected.httpStatus||"—"}}</dd></div><div><dt>耗时</dt><dd>{{selected.durationMs==null?"—":`${selected.durationMs} ms`}}</dd></div><div><dt>Retry-After</dt><dd>{{selected.retryAfter??"—"}}</dd></div><div><dt>请求 ID</dt><dd>{{selected.requestId||"—"}}</dd></div></dl><section class="relation-panel"><h2>关联关系</h2><p>{{selected.marketHashName||"未绑定具体物品"}} · {{selected.caller||"guadao"}} · {{selected.operation||"未知操作"}}</p><RouterLink v-if="relatedOperationQuery" :to="{path:'/guadao/operations',query:{q:relatedOperationQuery}}">前往关联流水</RouterLink></section><section v-if="Object.keys(requestFrequency).length" class="frequency-panel"><h2>近期 Steam 请求频率</h2><dl><div v-for="(value,key) in requestFrequency" :key="key"><dt>{{key}}</dt><dd>{{value}}</dd></div></dl></section><section v-if="redactedError" class="error-panel"><h2>脱敏错误摘要</h2><p>{{redactedError}}</p></section><section><h2>结构化详情</h2><pre>{{JSON.stringify(selected.detail||{},null,2)}}</pre></section><section class="privacy-note"><FolioIcon name="shield" :size="15" /><span>Cookie、token、Steam Guard、密码、密钥和 trade URL 不会写入日志或导出文件。</span></section></template><div v-else class="empty-state">选择一条日志查看脱敏详情。</div></aside>
    </section>
  </main>
</template>

<style scoped>
.logs-page{width:min(1380px,calc(100vw - 44px));gap:14px}.logs-heading{display:flex;justify-content:space-between;align-items:center;padding:7px 8px}.logs-heading h1{margin:0;font-size:32px;letter-spacing:-.045em}.logs-heading p:last-child{margin:6px 0 0;color:var(--folio-muted);font-size:11px}.stream-actions{display:flex;align-items:center;gap:8px}.stream-actions button{display:inline-flex;align-items:center;gap:6px}.stream-state{display:flex;align-items:center;gap:6px;color:var(--folio-muted);font-size:10px}.stream-state i{width:7px;height:7px;border-radius:50%;background:#9ca49f}.stream-state.online{color:var(--folio-green)}.stream-state.online i{background:currentColor}.api-error{margin:0;border-radius:10px;padding:9px 12px;color:var(--folio-red);background:var(--folio-red-soft);font-size:12px}.log-metrics{display:grid;grid-template-columns:.75fr 1.1fr .8fr .7fr 1.65fr;gap:10px}.log-metrics article{min-height:76px;display:grid;align-content:space-between;border:1px solid var(--folio-line);border-radius:14px;padding:12px 14px;background:#fff}.log-metrics span{color:var(--folio-muted);font-size:9px}.log-metrics strong{font-size:12px}.log-filters{padding:14px}.filter-row{display:grid;grid-template-columns:1.15fr 1.15fr .65fr .65fr .9fr;gap:10px}.filter-row.second{grid-template-columns:.7fr .8fr 1.2fr .9fr 1.2fr;margin-top:10px}.filter-row.third{display:flex;justify-content:space-between;align-items:end;margin-top:8px}.filter-row label{display:grid;gap:5px}.filter-row label>span{color:var(--folio-muted);font-size:9px}.filter-row input,.filter-row select{width:100%;min-height:37px;border:1px solid #dfe4df;border-radius:9px;padding:7px 9px;background:#fff}.scheduler-check{display:flex!important;flex-direction:row;align-items:center;gap:7px;padding-top:8px}.scheduler-check input{width:15px;min-height:15px;accent-color:var(--folio-green)}.filter-actions{display:flex;align-items:end;gap:6px}.filter-actions button{min-height:37px;padding:7px 10px;white-space:nowrap}.log-workbench{display:grid;grid-template-columns:minmax(0,3fr) minmax(310px,.82fr);gap:11px;align-items:start}.log-table-panel{padding:0;overflow:hidden}.log-table{min-width:1130px}.log-table th,.log-table td{padding:7px 8px;font-size:9px}.log-table td:last-child{max-width:270px;overflow:hidden;text-overflow:ellipsis}.log-table tbody tr{cursor:pointer}.log-table tbody tr.selected{background:#f0f7f3}.log-table tbody tr.warn{box-shadow:inset 3px 0 0 var(--folio-amber)}.log-table tbody tr.error{box-shadow:inset 3px 0 0 var(--folio-red)}.level-pill{display:inline-flex;border-radius:999px;padding:3px 6px;color:var(--folio-green);background:var(--folio-green-soft);font-size:8px;font-weight:800}.level-pill.warn{color:var(--folio-amber);background:var(--folio-amber-soft)}.level-pill.error{color:var(--folio-red);background:var(--folio-red-soft)}.http-error{color:var(--folio-red)!important;font-weight:750}.pagination{display:flex;justify-content:flex-end;align-items:center;gap:7px;padding:11px 13px;color:var(--folio-muted);font-size:9px}.pagination span{margin-right:auto}.pagination select,.pagination button{min-height:29px;border:1px solid var(--folio-line);border-radius:7px;padding:4px 8px;background:#fff}.log-detail{position:sticky;top:122px;min-height:520px}.log-detail header{display:flex;justify-content:space-between;border-bottom:1px solid var(--folio-line);padding-bottom:10px}.log-detail header span{color:var(--folio-green);font-size:9px}.log-detail dl{display:grid;gap:0;margin:10px 0}.log-detail dl div{display:grid;grid-template-columns:95px 1fr;gap:6px;border-bottom:1px solid #edf0ed;padding:7px 0}.log-detail dt{color:var(--folio-muted);font-size:8px}.log-detail dd{margin:0;overflow-wrap:anywhere;font-size:9px;font-weight:650}.log-detail section{margin-top:13px}.log-detail h2{font-size:12px}.log-detail pre{max-height:220px;overflow:auto;border:1px solid var(--folio-line);border-radius:9px;padding:9px;color:#45554d;background:var(--folio-surface-soft);font:9px/1.6 Consolas,monospace;white-space:pre-wrap}.relation-panel,.frequency-panel,.error-panel{border:1px solid var(--folio-line);border-radius:10px;padding:9px;background:var(--folio-surface-soft)}.relation-panel p,.error-panel p{margin:0;color:var(--folio-muted);font-size:9px;line-height:1.55}.relation-panel a{display:inline-flex;margin-top:7px;color:var(--folio-green);font-size:9px;font-weight:750;text-decoration:none}.frequency-panel dl{grid-template-columns:repeat(2,1fr);gap:5px;margin:0!important}.frequency-panel dl div{display:grid!important;grid-template-columns:1fr auto!important;border:0!important;border-radius:7px;padding:6px!important;background:#fff}.error-panel{border-color:#e9c0ba;background:var(--folio-red-soft)}.error-panel p{color:var(--folio-red)}.privacy-note{display:flex;gap:7px;border-radius:9px;padding:9px;color:#6d5a22;background:var(--folio-amber-soft);font-size:9px;line-height:1.6}.empty-state{margin:14px;border:1px dashed #d8ded9;border-radius:11px;padding:28px;color:var(--folio-muted);text-align:center;background:var(--folio-surface-soft);font-size:11px}
</style>
